    if (subsurface > 0.0) backScatter = pow(clamp(dot(viewDirection, -L), 0.0, 1.0), 4.0);
    if (NoL <= 0.0 && wrappedNoL <= 0.0 && backScatter <= 0.0) return vec3(0.0);

